CREATE TABLE stats (name TEXT, shots INTEGER, hits INTEGER);
INSERT INTO stats VALUES
  ('V', 50, 40),
  ('Judy', 40, 30),
  ('Jackie', 25, 10);

SELECT name,
       ROUND(hits * 100.0 / shots, 1) AS accuracy
FROM stats
ORDER BY accuracy DESC;

CREATE TABLE players (id INTEGER PRIMARY KEY, name TEXT, sponsor_id INTEGER, score INTEGER);
